216	    /// Ride summaries without track points.  Track points are stored per ride
217	    /// under `RideTracks/` so the defaults payload stays small no matter how
218	    /// long the rides are — a few hundred bytes per ride instead of megabytes.
219	    func loadRecordedRides() -> [NinebotRecordedRide] {
220	        guard let data = defaults.data(forKey: Key.recordedRides),
221	              let rides = try? decoder.decode([NinebotRecordedRide].self, from: data) else {
222	            return []
223	        }
224	
225	        // Records written before the split still carry their points inline.
226	        if rides.contains(where: { !$0.points.isEmpty }) {
227	            let migrated = rides.map { ride in
228	                writeTrackPoints(ride.points, id: ride.id)
229	                return ride.trackSummary()
230	            }
231	            persistRecordedRideSummaries(migrated)
232	            return migrated.sorted { $0.startedAt > $1.startedAt }
233	        }
234	
235	        return rides.sorted { $0.startedAt > $1.startedAt }
236	    }
