238	    /// A single ride with its track points read back from disk.
239	    func loadRecordedRide(id: String) -> NinebotRecordedRide? {
240	        guard let summary = loadRecordedRides().first(where: { $0.id == id }) else { return nil }
241	        return summary.withTrack(loadTrackPoints(id: id))
242	    }
