244	    func loadTrackPoints(id: String) -> [NinebotRideTrackPoint] {
245	        guard let url = trackPointsURL(id: id),
246	              let data = try? Data(contentsOf: url),
247	              let points = try? decoder.decode([NinebotRideTrackPoint].self, from: data) else {
248	            return []
249	        }
250	        return points
251	    }
252	
253	    func saveRecordedRides(_ rides: [NinebotRecordedRide]) {
254	        let sorted = rides.sorted { $0.startedAt > $1.startedAt }
255	        let retained = Array(sorted.prefix(120))
256	
257	        for ride in sorted.dropFirst(retained.count) {
258	            removeTrackPoints(id: ride.id)
259	        }
260	
261	        let summaries = retained.map { ride -> NinebotRecordedRide in
262	            // An unloaded summary must not overwrite the track already on disk.
263	            if !ride.points.isEmpty || ride.trackPointCount == 0 {
264	                writeTrackPoints(ride.points, id: ride.id)
265	            }
266	            return ride.trackSummary()
267	        }
268	
269	        persistRecordedRideSummaries(summaries)
270	    }
271	
272	    func upsertRecordedRide(_ ride: NinebotRecordedRide) {
273	        var rides = loadRecordedRides()
274	        if let index = rides.firstIndex(where: { $0.id == ride.id }) {
275	            rides[index] = ride
276	        } else {
277	            rides.insert(ride, at: 0)
278	        }
279	        saveRecordedRides(rides)
280	    }
