288	    func recordedTrackByteCount() -> Int {
289	        guard let directory = trackPointsDirectoryURL(),
290	              let names = try? FileManager.default.contentsOfDirectory(atPath: directory.path) else {
291	            return 0
292	        }
293	        return names.reduce(0) { total, name in
294	            let attributes = try? FileManager.default.attributesOfItem(
295	                atPath: directory.appendingPathComponent(name).path
296	            )
297	            return total + ((attributes?[.size] as? Int) ?? 0)
298	        }
299	    }
