306	    private func writeTrackPoints(_ points: [NinebotRideTrackPoint], id: String) {
307	        guard let url = trackPointsURL(id: id) else { return }
308	
309	        guard !points.isEmpty else {
310	            try? FileManager.default.removeItem(at: url)
311	            return
312	        }
313	
314	        guard let data = try? encoder.encode(points) else { return }
315	        try? FileManager.default.createDirectory(
316	            at: url.deletingLastPathComponent(),
317	            withIntermediateDirectories: true
318	        )
319	        try? data.write(to: url, options: .atomic)
320	    }
321	
322	    private func removeTrackPoints(id: String) {
323	        guard let url = trackPointsURL(id: id) else { return }
324	        try? FileManager.default.removeItem(at: url)
325	    }
