422	    private func saveHistorySnapshots(for dashboard: NinebotDashboard) {
423	        for snapshot in dashboard.vehicles {
424	            let point = NinebotVehicleHistoryPoint(sn: snapshot.vehicle.sn, state: snapshot.state)
425	            var points = loadHistory(sn: snapshot.vehicle.sn)
426	            guard shouldAppend(point, after: points.last) else { continue }
427	
428	            points.append(point)
429	            if points.count > 240 {
430	                points.removeFirst(points.count - 240)
431	            }
432	
433	            guard let data = try? encoder.encode(points) else { continue }
434	            defaults.set(data, forKey: historyKey(sn: snapshot.vehicle.sn))
435	        }
436	    }
