438	    private func dashboardWithArchivedInterfaceRides(_ dashboard: NinebotDashboard) -> NinebotDashboard {
439	        var archivedDashboard = dashboard
440	
441	        for index in archivedDashboard.vehicles.indices {
442	            let sn = archivedDashboard.vehicles[index].vehicle.sn
443	            let incomingRecords = archivedDashboard.vehicles[index].state.rides
444	            guard !incomingRecords.isEmpty else {
445	                let storedRecords = loadInterfaceRideRecords(sn: sn)
446	                if !storedRecords.isEmpty {
447	                    archivedDashboard.vehicles[index].state.rideRecords = storedRecords
448	                }
449	                continue
450	            }
451	
452	            let mergedRecords = mergeInterfaceRideRecords(
453	                incoming: incomingRecords,
454	                stored: loadInterfaceRideRecords(sn: sn)
455	            )
456	            saveInterfaceRideRecords(mergedRecords, sn: sn)
457	            archivedDashboard.vehicles[index].state.rideRecords = mergedRecords.isEmpty ? nil : mergedRecords
458	        }
459	
460	        return archivedDashboard
461	    }
