463	    private func loadInterfaceRideRecords(sn: String) -> [NinebotRideRecord] {
464	        guard let data = defaults.data(forKey: interfaceRideKey(sn: sn)),
465	              let records = try? decoder.decode([NinebotRideRecord].self, from: data) else {
466	            return []
467	        }
468	        return sortedInterfaceRideRecords(deduplicatedInterfaceRideRecords(records))
469	    }
470	
471	    private func saveInterfaceRideRecords(_ records: [NinebotRideRecord], sn: String) {
472	        let limited = Array(sortedInterfaceRideRecords(deduplicatedInterfaceRideRecords(records)).prefix(500))
473	        guard let data = try? encoder.encode(limited) else { return }
474	        defaults.set(data, forKey: interfaceRideKey(sn: sn))
475	    }
476	
477	    private func mergeInterfaceRideRecords(
478	        incoming: [NinebotRideRecord],
479	        stored: [NinebotRideRecord]
480	    ) -> [NinebotRideRecord] {
481	        var recordsByKey: [String: NinebotRideRecord] = [:]
482	
483	        for record in stored {
484	            recordsByKey[interfaceRideKey(for: record)] = record
485	        }
486	
487	        for record in incoming {
488	            recordsByKey[interfaceRideKey(for: record)] = record
489	        }
490	
491	        return sortedInterfaceRideRecords(Array(recordsByKey.values))
492	    }
493	
494	    private func deduplicatedInterfaceRideRecords(_ records: [NinebotRideRecord]) -> [NinebotRideRecord] {
495	        var recordsByKey: [String: NinebotRideRecord] = [:]
496	
497	        for record in records {
498	            recordsByKey[interfaceRideKey(for: record)] = record
499	        }
500	
501	        return Array(recordsByKey.values)
502	    }
503	
504	    private func sortedInterfaceRideRecords(_ records: [NinebotRideRecord]) -> [NinebotRideRecord] {
505	        records.sorted { left, right in
506	            let leftDate = left.startedAt ?? left.endedAt ?? .distantPast
507	            let rightDate = right.startedAt ?? right.endedAt ?? .distantPast
508	            if leftDate != rightDate {
509	                return leftDate > rightDate
510	            }
511	            return interfaceRideKey(for: left) < interfaceRideKey(for: right)
512	        }
513	    }
514	
515	    private func interfaceRideKey(for record: NinebotRideRecord) -> String {
516	        record.stableIdentityKey
517	    }
518	
519	    private func shouldAppend(
520	        _ point: NinebotVehicleHistoryPoint,
521	        after last: NinebotVehicleHistoryPoint?
522	    ) -> Bool {
523	        guard let last else { return true }
524	
525	        let hasSameValues = last.battery == point.battery
526	            && last.endurance == point.endurance
527	            && last.totalMileage == point.totalMileage
528	            && last.isCharging == point.isCharging
529	            && last.isLocked == point.isLocked
530	            && last.isPoweredOn == point.isPoweredOn
531	
532	        if abs(point.date.timeIntervalSince(last.date)) < 60, hasSameValues {
533	            return false
534	        }
535	
536	        if point.date.timeIntervalSince(last.date) < 300, hasSameValues {
537	            return false
538	        }
539	
540	        return true
541	    }
