570	    private func vehicleImageCacheURL(sn: String) -> URL? {
571	        let baseURL = FileManager.default.containerURL(forSecurityApplicationGroupIdentifier: NinebotAppGroup.identifier)
572	            ?? FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask).first
573	        let fileName = sanitizedFileName(sn)
574	        return baseURL?
575	            .appendingPathComponent("VehicleImages", isDirectory: true)
576	            .appendingPathComponent("\(fileName).image")
577	    }
