579	    private func sanitizedFileName(_ value: String) -> String {
580	        let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "-_"))
581	        let scalars = value.unicodeScalars.map { allowed.contains($0) ? Character($0) : "_" }
582	        let text = String(scalars)
583	        return text.isEmpty ? "vehicle" : text
584	    }
