            return "\(Self.numberText(hours / 24, maximumFractionDigits: 1)) 天"
        }
        if hours >= 1 {
            return "\(Self.numberText(hours, maximumFractionDigits: 1)) 小时"
        }
        return "\(Self.numberText(seconds / 60, maximumFractionDigits: 0)) 分钟"
    }

